Supuesto OEP 2008 (formulario web de proyectos de las CCAA, plataforma .NET, Internet Explorer 6). Función JavaScript del enunciado (se reproduce tal cual, con sus erratas):
```
function ValidarFecha() {
 var mensaje="Sin Error"; var sw=0;
 var fecha= document.forms[0].fecha.value;
 If (fecha=="") { mensaje = "0"; sw=1; }
 else {
  if (fecha.length<10) { mensaje = "1"; sw=1; }
  else {
   var dia=fecha.charAt(0)+fecha.charAt(1);
   var mes=fecha.charAt(3)+fecha.charAt(4);
   var ano=fecha.charAt(6)+fecha.charAt(7)+fecha.charAt(8)+fecha.charAt(9);
  }
 }
 If (sw=="0") {
  if (dia.charAt(0)=="/" || dia.charAt(1)=="/" || mes.charAt(0)=="/" || mes.charAt(1)=="/" || ano.charAt(0)=="/" || ano.charAt(1)=="/") { mensaje = "2"; }
  else { if (dia<1 || dia>31 || mes<1 || mes>12 || ano.length<4) { mensaje = "3"; }
   else { if ((mes==2 || mes==4 || mes==6 || mes==9 || mes==11) && dia>30) { mensaje = "4"; }
    else { if ((ano%4 != 0) && (dia>28) && (mes==2)) { mensaje = "5"; } } } }
 }
 alert("Error"+mensaje);
}
```

